const ctx = $input.first().json;
const config = $('Config').first().json;

if (!ctx.profile?.id) {
  throw new Error('CONTENT_STUDIO: No business profile returned. Create and approve the profile in admin → Content.');
}
if (ctx.profile.status !== 'approved') {
  throw new Error(`CONTENT_STUDIO: Profile "${ctx.profile.title}" is not approved (status=${ctx.profile.status}).`);
}
if (!Array.isArray(ctx.topics) || ctx.topics.length === 0) {
  throw new Error('CONTENT_STUDIO: No Ready topics. Set at least one topic to Ready in admin → Content.');
}
if (!Array.isArray(ctx.sources)) {
  throw new Error('CONTENT_STUDIO: Invalid API response (sources).');
}

return [{
  json: {
    ...ctx,
    siteBaseUrl: config.siteBaseUrl,
    connectivityTest: config.connectivityTest === true,
  },
}];

const item = $input.first().json;
const today = new Date().toISOString().slice(0, 10);

const dueTopics = item.topics.filter((t) => {
  const d = t.data?.plannedDate;
  return !d || d <= today;
});

const pool = dueTopics.length ? dueTopics : item.topics;

const sorted = [...pool].sort((a, b) => {
  const pa = Number(a.data?.priority ?? 99);
  const pb = Number(b.data?.priority ?? 99);
  return pa - pb;
});

const topic = sorted[0];
if (!topic?.id) {
  throw new Error('CONTENT_STUDIO: Topic selection failed.');
}

const titleLower = topic.title.trim().toLowerCase();
const duplicate = (item.existingArticles ?? []).some(
  (a) => a.title?.trim().toLowerCase() === titleLower,
);
if (duplicate) {
  throw new Error(`CONTENT_STUDIO: Topic "${topic.title}" matches an existing article title. Rename the topic or archive the article.`);
}

function slugify(raw) {
  const base = raw
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 120);
  if (/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(base)) return base;
  const fallback = `topic-${topic.id}`.toLowerCase().replace(/[^a-z0-9-]/g, '');
  return fallback || `topic-${topic.id}`;
}

const requestKey = `topic-${topic.id}-draft-v1`;

return [{
  json: {
    siteBaseUrl: item.siteBaseUrl,
    connectivityTest: item.connectivityTest,
    profile: item.profile,
    sources: item.sources,
    existingArticles: item.existingArticles,
    topic,
    requestKey,
    suggestedSlug: slugify(topic.title),
  },
}];

const row = $input.first().json;
const topic = row.topic;

// Phase A: connectivity placeholder. Replace this block with OpenAI output in Phase B.
let title;
let slug;
let data;

if (row.connectivityTest) {
  title = `Draft for ${topic.title}`.slice(0, 200);
  slug = row.suggestedSlug;
  data = {
    excerpt: 'Connectivity test — replace with model output before production scheduling.',
    body: '## Connectivity test\n\nThis draft was created by the n8n template. Disable connectivityTest in Config after verification.',
    metaTitle: title.slice(0, 100),
    metaDescription: 'Placeholder draft from Content Studio automation.',
    keyword: topic.data?.keyword ?? '',
    sources: 'Connectivity test — no model run.',
    sourceIds: [],
  };
} else {
  throw new Error('CONTENT_STUDIO: connectivityTest is false but no OpenAI node is wired. Add generation or set connectivityTest true.');
}

const delivery = {
  requestKey: row.requestKey,
  topicId: topic.id,
  title,
  slug,
  data,
};

return [{
  json: {
    siteBaseUrl: row.siteBaseUrl,
    topicId: topic.id,
    topicTitle: topic.title,
    delivery,
  },
}];
